void*operator new(std::size_t n){if(watch)++allocations;if(auto*p=std::malloc(n?n:1))return p;std::abort();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
#define CHECK(x) do{if(!(x)){std::fprintf(stderr,"FAIL %d %s\n",__LINE__,#x);std::exit(1);}}while(false)
using namespace blocks_detail;using Frame=std::array<double,2>;constexpr double pi=3.14159265358979323846;
template<class T>static Frame tick(T&x,double l=0,double r=0){watch=true;x.process(l,r);watch=false;CHECK(std::isfinite(l)&&std::isfinite(r));return{l,r};}
static double power(const std::vector<Frame>&x,unsigned from=0,unsigned to=0){if(!to)to=unsigned(x.size());double p=0;for(unsigned i=from;i<to;++i)p+=x[i][0]*x[i][0]+x[i][1]*x[i][1];return p/(to-from);}
template<class T>static std::vector<Frame>render(bs_creative_fx_block c,const std::vector<Frame>&in,double rate=8000){T p;CHECK(p.configure(c,true)&&p.prepare(rate));std::vector<Frame>out(in.size());for(unsigned i=0;i<in.size();++i)out[i]=tick(p,in[i][0],in[i][1]);return out;}
static double difference(const std::vector<Frame>&a,const std::vector<Frame>&b){double scale=std::sqrt(power(a)/std::max(1e-30,power(b))),e=0;for(unsigned i=0;i<a.size();++i)for(unsigned ch=0;ch<2;++ch)e+=std::pow(a[i][ch]-scale*b[i][ch],2);return std::sqrt(e/a.size()/power(a));}
static double bandPower(const std::vector<Frame>&x,double low,double high,unsigned from,double rate=8000){unsigned n=unsigned(x.size())-from;double p=0;for(unsigned k=unsigned(std::ceil(low*n/rate));k<=unsigned(std::floor(high*n/rate));++k){double coeff=2*std::cos(2*pi*k/n);for(unsigned ch=0;ch<2;++ch){double a=0,b=0;for(unsigned i=from;i<x.size();++i){double v=x[i][ch]+coeff*a-b;b=a;a=v;}p+=(a*a+b*b-coeff*a*b)/(double(n)*n);}}return p;}
